<?php $success=sessionSuccess();$errors=sessionErrors();$today=date('Y-m-d');?><!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Meals</title><style>*{box-sizing:border-box}body{font-family:Arial;background:#f7f9fc;color:#172033;margin:0}.top{background:#fff;padding:18px 6%;border-bottom:1px solid #e7ebf2}.top a{color:#2563eb}main{max-width:1050px;margin:auto;padding:30px 24px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.panel{background:#fff;border:1px solid #e7ebf2;border-radius:8px;padding:20px;margin-bottom:18px}label{display:block;font-weight:600;font-size:13px;margin:9px 0 5px}input,select,textarea,button{width:100%;padding:9px;border:1px solid #cbd5e1;border-radius:6px;font:inherit}textarea{min-height:75px}button{background:#2563eb;color:#fff;margin-top:10px}.message{padding:10px;background:#dcfce7;color:#166534;margin-bottom:12px}.error{background:#fee2e2}.item{border-bottom:1px solid #e7ebf2;padding:9px;font-size:13px}.muted{color:#718096;font-size:13px}.ratings{display:grid;grid-template-columns:1fr 1fr;gap:10px}@media(max-width:760px){.grid,.ratings{grid-template-columns:1fr}}</style></head><body><header class="top"><a href="/student/dashboard">Back to dashboard</a></header><main><h1>Meals</h1><?php if($success):?><div class="message"><?=htmlspecialchars($success)?></div><?php endif;?><?php foreach($errors as $group):foreach((array)$group as $error):?><div class="message error"><?=htmlspecialchars($error)?></div><?php endforeach;endforeach;?><section class="panel"><h2>Menu</h2><?php if($menus):foreach($menus as $menu):?><div class="item"><strong><?=htmlspecialchars(ucfirst($menu['meal_type']))?> · <?=htmlspecialchars($menu['menu_date'])?></strong><br><?=nl2br(htmlspecialchars($menu['items']))?></div><?php endforeach;else:?><p class="muted">No menus published yet.</p><?php endif;?></section><section class="panel"><h2>Attendance</h2><?php if($attendance):foreach($attendance as $item):?><div class="item"><?=htmlspecialchars($item['attendance_date'])?> · <?=htmlspecialchars(ucfirst($item['meal_type']))?> · <?=htmlspecialchars(ucfirst($item['status']))?></div><?php endforeach;else:?><p class="muted">No attendance records yet.</p><?php endif;?></section><div class="grid"><section class="panel"><h2>Meal Feedback</h2><form method="post" action="/student/meal-feedback-store"><label>Meal</label><select name="meal_type" required><option value="breakfast">Breakfast</option><option value="lunch">Lunch</option><option value="dinner">Dinner</option></select><label>Date</label><input name="feedback_date" type="date" value="<?=$today?>" required><label>How was the food? (0-5)</label><input name="rating" type="number" min="0" max="5" value="0" required><div class="ratings"><div><label>Taste</label><input name="taste_rating" type="number" min="0" max="5" value="0" required></div><div><label>Quality</label><input name="quality_rating" type="number" min="0" max="5" value="0" required></div><div><label>Quantity</label><input name="quantity_rating" type="number" min="0" max="5" value="0" required></div><div><label>Hygiene</label><input name="hygiene_rating" type="number" min="0" max="5" value="0" required></div></div><label>Comments</label><textarea name="comment" placeholder="Write your feedback..."></textarea><button type="submit">Submit Feedback</button></form></section><section class="panel"><h2>Food Complaint</h2><form method="post" action="/student/food-complaint-store" enctype="multipart/form-data"><label>Meal Type</label><select name="meal_type" required><option value="breakfast">Breakfast</option><option value="lunch">Lunch</option><option value="dinner">Dinner</option></select><label>Complaint Category</label><select name="category" required><option value="taste">Taste</option><option value="quality">Quality</option><option value="quantity">Quantity</option><option value="hygiene">Hygiene</option><option value="other">Other</option></select><label>Date</label><input name="complaint_date" type="date" value="<?=$today?>" required><label>Description</label><textarea name="description" required></textarea><label>Photo (Optional)</label><input name="photo" type="file" accept="image/jpeg,image/png,image/webp"><button type="submit">Submit Complaint</button></form></section></div><section class="panel"><h2>My submissions</h2><?php foreach($feedback as $item):?><div class="item">Feedback: <?=htmlspecialchars($item['meal_type'])?> · Overall <?= (int)$item['rating']?>/5</div><?php endforeach;?><?php foreach($complaints as $item):?><div class="item">Complaint: <?=htmlspecialchars($item['meal_type'])?> · <?=htmlspecialchars($item['category'])?> · <?=htmlspecialchars($item['status'])?></div><?php endforeach;?></section></main></body></html>
